-- Local disposable PostgreSQL only; no customer data and no outbound notifications.
BEGIN;
CREATE FUNCTION pg_temp.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',msg;END IF;END$$;
CREATE FUNCTION pg_temp.reject(q text, expected text DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$BEGIN BEGIN EXECUTE q;EXCEPTION WHEN OTHERS THEN IF expected IS NOT NULL AND position(expected in SQLERRM)=0 THEN RAISE;END IF;RETURN;END;RAISE EXCEPTION 'Expected rejection: %',q;END$$;
INSERT INTO auth.users(id,email) VALUES('00000000-0000-0000-0000-000000000001','admin@test.invalid'),('00000000-0000-0000-0000-000000000002','buyer@test.invalid'),('00000000-0000-0000-0000-000000000003','owner@test.invalid');
INSERT INTO admin_profiles(id,email) VALUES('00000000-0000-0000-0000-000000000001','admin@test.invalid');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
INSERT INTO restaurants(id,name,phone,email,type,owner_id,lat,lng,address,is_open,status) VALUES('00000000-0000-0000-0000-000000000010','QA','1234567890','qa@test.invalid','Restaurantes','00000000-0000-0000-0000-000000000003',20,-102,'Calle de prueba 123',true,'ACTIVE');
SELECT pg_temp.assert((SELECT status='PENDING' AND NOT is_open FROM restaurants),'registration cannot self-approve');
SELECT pg_temp.reject($q$UPDATE restaurants SET status='ACTIVE' WHERE id='00000000-0000-0000-0000-000000000010'$q$);
SELECT pg_temp.reject($q$SELECT admin_business_map()$q$);
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
SELECT pg_temp.reject($q$UPDATE restaurants SET status='ACTIVE' WHERE id='00000000-0000-0000-0000-000000000010'$q$);
SELECT admin_verify_business_location('00000000-0000-0000-0000-000000000010','Calle de prueba 123',20,-102,'Entrada principal');
UPDATE restaurants SET status='ACTIVE',is_open=true WHERE id='00000000-0000-0000-0000-000000000010';
SELECT pg_temp.assert((admin_business_map()->>'total_businesses')::int=1,'map includes business');
SELECT admin_save_category(NULL,'Restaurantes','prepared','public',10,NULL);
SELECT pg_temp.assert((SELECT NOT is_active AND release_mode='closed' FROM app_categories WHERE name='Restaurantes'),'new category always closed');
UPDATE app_categories SET is_active=true,release_mode='public' WHERE name='Restaurantes';
INSERT INTO menu_items(id,restaurant_id,name,price) VALUES('00000000-0000-0000-0000-000000000012','00000000-0000-0000-0000-000000000010','QA Pizza',100);
SELECT pg_temp.reject($q$SELECT admin_save_category((SELECT id FROM app_categories WHERE name='Restaurantes'),'Renombrada','prepared','public',10,NULL)$q$);
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
DO $$BEGIN FOR i IN 1..4 LOOP INSERT INTO orders(restaurant_id,client_user_id,client_name,client_phone,client_lat,client_lng,items,subtotal,commission_amount,delivery_amount,total,status,payment_method,delivery_type) VALUES('00000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000000002','QA','3300000000',20,-102,'[{"id":"00000000-0000-0000-0000-000000000012","name":"QA Pizza","price":100,"quantity":1}]',100,8,0,108,'PENDING','cash','delivery');END LOOP;END$$;
SELECT pg_temp.reject($q$INSERT INTO orders(restaurant_id,client_user_id,client_name,client_phone,client_lat,client_lng,items,subtotal,commission_amount,delivery_amount,total,status,payment_method,delivery_type) VALUES('00000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000000002','QA','3300000000',20,-102,'[]',100,8,0,108,'PENDING','cash','delivery')$q$,'Tienes cuatro pedidos');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
SELECT pg_temp.assert((admin_platform_report(current_date,current_date)->'summary'->>'total')::int=4,'report counts all pending');
SELECT pg_temp.assert((admin_platform_report(current_date,current_date)->'summary'->>'sales')::numeric=0,'pending orders are not sales');
SELECT pg_temp.assert((admin_platform_report(current_date,current_date)->'summary'->>'cycle_minutes') IS NULL,'missing durations are not zero');
SELECT pg_temp.assert((admin_business_map()->>'active_orders')::int=4,'active map order count');
SELECT pg_temp.reject($q$SELECT admin_verify_business_location('00000000-0000-0000-0000-000000000010','Otra calle 456',21,-102,'Otro acceso')$q$);
SELECT report_order_abuse((SELECT id FROM orders LIMIT 1),'Pedido de prueba con evidencia');
SELECT pg_temp.reject($q$SELECT report_order_abuse((SELECT id FROM orders LIMIT 1),'Reporte duplicado del pedido')$q$);
SELECT admin_restrict_account('00000000-0000-0000-0000-000000000002','Abuso verificado en QA',1);
SELECT pg_temp.assert((SELECT expires_at>now() AND expires_at<=now()+interval '1 hour' FROM account_restrictions),'restriction expires');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
SELECT pg_temp.reject($q$INSERT INTO orders(restaurant_id,client_user_id,client_name,client_phone,items,subtotal,total,status) VALUES('00000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000000002','QA','3300000000','[]',100,100,'PENDING')$q$,'restricción temporal');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
SELECT admin_revoke_restriction((SELECT id FROM account_restrictions),'Revisión y retiro de prueba');
SELECT pg_temp.assert((SELECT revoked_at IS NOT NULL FROM account_restrictions),'restriction revoked with audit');
SELECT pg_temp.assert((SELECT count(*)>=2 FROM operation_audit WHERE action LIKE 'ACCOUNT_%'),'restriction audit exists');
ROLLBACK;
